static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // Input 0: x of shape [N, Cin, Lin]
    // Input 1: weight of shape [Cin, Cout, K] (PyTorch ConvTranspose1d default)
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    if (x_shape->GetDimNum() != 3 || w_shape->GetDimNum() != 3) {
        return ge::GRAPH_FAILED;
    }

    int64_t N = x_shape->GetDim(0);
    int64_t Cin = x_shape->GetDim(1);
    int64_t Lin = x_shape->GetDim(2);

    int64_t CinW = w_shape->GetDim(0);
    int64_t Cout = w_shape->GetDim(1);
    int64_t K = w_shape->GetDim(2);

    if (CinW != Cin) {
        return ge::GRAPH_FAILED;
    }

    int64_t stride   = get_int_attr(context, "stride", 1);
    int64_t padding  = get_int_attr(context, "padding", 0);
    int64_t dilation = get_int_attr(context, "dilation", 1);
    // output_padding assumed 0
    int64_t Lout = (Lin - 1) * stride - 2 * padding + dilation * (K - 1) + 1;

    ConvTransposed1dDilatedCustomTilingData tiling;
    context->SetBlockDim(BLOCK_DIM);

    uint64_t totalLength = static_cast<uint64_t>(N) * static_cast<uint64_t>(Cout) * static_cast<uint64_t>(Lout);

    tiling.set_N(static_cast<uint32_t>(N));
    tiling.set_Cin(static_cast<uint32_t>(Cin));
    tiling.set_Cout(static_cast<uint32_t>(Cout));
    tiling.set_Lin(static_cast<uint32_t>(Lin));
    tiling.set_Lout(static_cast<uint32_t>(Lout));
    tiling.set_K(static_cast<uint32_t>(K));
    tiling.set_stride(static_cast<int32_t>(stride));
    tiling.set_padding(static_cast<int32_t>(padding));
    tiling.set_dilation(static_cast<int32_t>(dilation));
    tiling.set_totalLength(static_cast<uint32_t>(totalLength));
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
