at::Tensor conv_transposed_1d_dilated_custom_impl_npu(const at::Tensor& x,
                                                      const at::Tensor& weight,
                                                      int64_t stride,
                                                      int64_t padding,
                                                      int64_t dilation) {
    TORCH_CHECK(x.dim() == 3, "x must be [N, Cin, Lin]");
    TORCH_CHECK(weight.dim() == 3, "weight must be [Cin, Cout, K]");

    auto N = x.size(0);
    auto Cin = x.size(1);
    auto Lin = x.size(2);

    TORCH_CHECK(weight.size(0) == Cin, "weight dim 0 must equal Cin");
    auto Cout = weight.size(1);
    auto K = weight.size(2);

    // output_padding = 0
    int64_t Lout = (Lin - 1) * stride - 2 * padding + dilation * (K - 1) + 1;
    at::Tensor y = at::empty({N, Cout, Lout}, x.options());

    // Attributes are registered to op; EXEC_NPU_CMD will pass attrs through internal context.
    EXEC_NPU_CMD(aclnnConvTransposed1dDilatedCustom, x, weight, y, stride, padding, dilation);
    return y;
